const items = $input.all();
return items.map(item => {
  const conversas = item.json.conversas || [];
  if (!Array.isArray(conversas)) throw new Error("A propriedade 'conversas' não é um array.");
  let phone = '';
  let email = '';
  let nomewpp = 'sem nome';
  for (const conversa of conversas) {
    if (conversa.phone && !phone) phone = conversa.phone;
    if (conversa.email && !email) email = conversa.email;
    if (conversa.nomewpp && nomewpp === 'sem nome') nomewpp = conversa.nomewpp;
  }
  const textoUnico = conversas.map(conversa => {
    const cliente = conversa.user_message || "sem mensagem do usuário";
    const agente = conversa.bot_message || "sem resposta do chatbot";
    const dataOriginal = conversa.created_at || "Data indisponível";
    const dataFormatada = dataOriginal !== "Data indisponível" ? formatarData(dataOriginal) : dataOriginal;
    return `em: ${dataFormatada}\n\n- agente(chatbot): ${agente}\n- cliente(${conversa.nomewpp || nomewpp}): ${cliente}\n`;
  }).join('\n\n');
  return { json: { texto: textoUnico, phone: phone, email: email, nomewpp: nomewpp, conversas_count: conversas.length, has_phone: !!phone, has_email: !!email, first_user_message: conversas[0]?.user_message || 'Nenhuma', first_bot_message: conversas[0]?.bot_message || 'Nenhuma' }, pairedItem: item };
});
function formatarData(dataString) {
  try {
    const data = new Date(dataString);
    if (isNaN(data.getTime())) return "Data inválida";
    const dia = String(data.getDate()).padStart(2, '0');
    const mes = String(data.getMonth() + 1).padStart(2, '0');
    const ano = data.getFullYear();
    const horas = String(data.getHours()).padStart(2, '0');
    const minutos = String(data.getMinutes()).padStart(2, '0');
    return `${dia}/${mes}/${ano} ${horas}:${minutos}`;
  } catch (error) { return "Data inválida"; }
}

const redis1 = JSON.parse($json.Redis1);
const redis2 = JSON.parse($json.Redis2);
const combinadoSemDuplicatas = Array.from(new Set([...redis1, ...redis2]));
const mensagem = combinadoSemDuplicatas.join(" ");
return [{ json: { mensagem_completa: mensagem } }];

